-attendance-notes'),tooltip:'Editar observações',onPressed:_loading?null:_editNotes,icon:const Icon(Icons.edit_note))]),const SizedBox(height:8),Text((s.notes?.trim().isNotEmpty??false)?s.notes!:'Nenhuma observação registrada.')]))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Resumo',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:12),Text('Subtotal: ${_money(s.subtotal)}'),Text('Descontos: ${_money(s.discountTotal)}'),const Divider(),Text('Total: ${_money(s.total)}',style:Theme.of(context).textTheme.titleLarge)]))),const SizedBox(height:12),OutlinedButton.icon(key:const Key('attendance-history-button'),onPressed:_loading?null:_showHistory,icon:const Icon(Icons.history),label:const Text('Ver histórico do atendimento')),const SizedBox(height:8),if(!s.isClosed)...[FilledButton.tonalIcon(onPressed:_loading?null:_addItem,icon:const Icon(Icons.add_shopping_cart),label:const Text('Adicionar produto/item extra')),const SizedBox(height:8),OutlinedButton.icon(onPressed:_loading?null:_finish,icon:const Icon(Icons.check_circle_outline),label:const Text('Finalizar atendimento'))]else const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Atendimento finalizado e preparado para recebimento.')))],if(_loading)const Padding(padding:EdgeInsets.only(top:16),child:LinearProgressIndicator())])));}}
